using AshkanCMS.Data; using AshkanCMS.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AshkanCMS.Areas.Admin.Controllers; [Area("Admin"),Authorize]
public class MediaController(AppDbContext db,IWebHostEnvironment env):Controller { public async Task<IActionResult> Index()=>View(await db.Media.OrderByDescending(x=>x.UploadedAt).ToListAsync()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Upload(IFormFile file,string? alt){if(file==null||file.Length==0)return RedirectToAction(nameof(Index));var allowed=new[]{".jpg",".jpeg",".png",".webp",".gif",".pdf"};var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(!allowed.Contains(ext)||file.Length>8*1024*1024){TempData["Error"]="Unsupported file or file is larger than 8 MB.";return RedirectToAction(nameof(Index));}var dir=Path.Combine(env.WebRootPath,"uploads");Directory.CreateDirectory(dir);var safe=$"{Guid.NewGuid():N}{ext}";await using(var fs=System.IO.File.Create(Path.Combine(dir,safe)))await file.CopyToAsync(fs);db.Media.Add(new MediaItem{FileName=Path.GetFileName(file.FileName),Url=$"/uploads/{safe}",Alt=alt??""});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var x=await db.Media.FindAsync(id);if(x!=null){db.Media.Remove(x);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
